INSERT INTO tennis_rules (source_file, rule_id, content, embedding) VALUES ('테니스규정집(2020.11.20 개정판).pdf', '2. 퍼머넌트 픽스쳐', '**2. 퍼머넌트 픽스쳐**
코트의 퍼머넌트 픽스쳐는 백스탑(backstop)과 사이드스탑(side stop), 관중,
스탠드 및 관중석, 코트 위와 그 주변의 모든 시설물, 체어엄파이어, 라인엄파
이어, 네트엄파이어(net umpire) 그리고 볼피플(ball persons)은 지정된 자기
자리를 지키는 한 그 모두가 포함된다.
복식네트와 싱글스틱을 갖춘 코트에서 단식경기를 하는 경우에는 네트포스트
와 싱글스틱 바깥쪽 사이의 네트 부분은 퍼머넌트 픽스쳐이며, 네트포스트나
네트의 일부분으로 간주되지 않는다.', '[-0.03309025723308934, 0.020677578194612287, -0.01927402158188794, -0.10935344903079959, 0.01479470046854193, 0.02691637240481932, -0.004030282911197595, 0.01168480853343926, 0.005973958176972954, 0.006644369855685584, -0.032476788517003086, -0.02763882252751141, -0.04287355854461984, -0.006059357713561013, 0.12055667037345656, -0.025849460190872038, 0.0033691169105647526, -0.04254533853285911, -0.013667439482172033, -0.04041351446352769, 0.023190843254009524, -0.013614639723217766, -0.002857284783663426, 0.020427604444151485, -0.023778778797101805, 0.002951259514195895, 0.0494702279956155, 0.039364586409106034, 0.060264233872247226, 0.009368373729757334, -0.027517483619868638, -0.009802675668255127, 0.028798702879081615, 0.024312456780935136, 0.025531016628241386, 0.053228470115925776, 0.03753128898742218, -0.0620180317750565, -0.02466099065924823, 0.01719793887331464, -0.03851561100717593, 0.002361044706394196, -0.012877494245421062, -0.008266567739456629, 0.011335135802807289, 0.004214685809333433, 0.0049292828779228795, -0.017178451844747207, -0.01261423059108874, -0.013119312634557897, 0.0373208370525936, -0.02759589282198739, 0.012099119366879015, -0.2951337864461973, -0.022547743576676913, -0.030624118472007585, 0.004531383478424402, -0.006791616006840458, -0.02454708462640506, 0.0106347532405656, -0.02869345871083117, 0.014074470847859705, 0.021702262735286918, -0.004124456464197302, -0.015433697157383254, 0.044945091044156546, -0.0027798121445703735, -0.026486692265313642, -0.030406524875757734, 0.010991978971515737, 0.014098707427954866, 0.0013341962249747922, 0.0007110329461869967, 0.0035968499326198226, 0.006905230826305283, -0.038164856626852976, 0.02458502036917309, -0.014979877508908527, -0.05503917249959358, 0.06961752742922142, -0.010450612781152864, -0.0609665781379429, -0.03789801156799093, -0.009073310267875181, 0.04909633081877913, -0.006231942028751148, -0.016518766872152795, 0.027449211416776947, -0.012239705225393378, -