INSERT INTO tennis_rules (source_file, rule_id, content, embedding) VALUES ('테니스규정집(2020.11.20 개정판).pdf', '2. 외부로부터의 방해', '**2. 외부로부터의 방해**
만일 선수가 경기 또는 서비스 동작이 진행되는 동안 자신의 통제에
있던 것이 벗어난 어떤 것(볼이 코트 안으로 들어오거나 종이가 코트 안으로
날아
오는 등)으로 인해 방해를 받았다면, 그 포인트는 다시 진행되어야 한다.
관중 소음, 관중석에서의 “Out” 콜 및 기타 유사한 주의를 분산시키는 행
위는 방해로 간주되지 않으며 그 포인트는 진행되었던 대로 유지되어야 한다.', '[-0.01283680934072334, 0.019944328627056036, 0.017891275663666644, -0.11861341245279035, 0.023786324031399134, 0.004715430103057814, -0.012203776631220799, 0.01317142525802846, 0.021894045902304274, 0.011296550304458839, 0.023881861224850243, 0.004763976815868356, -0.00422095856500209, 0.01924272411255442, 0.12082405082388398, -0.02555864505301902, 0.009613216711445471, -0.016348109742406546, -0.031427477720886596, -0.03317058602167712, 0.0257550547959239, 0.0015892880458437818, 0.0021568370779756043, 0.01228657206544373, -0.014895195926731374, -0.007731438729368707, 0.05822780467995118, 0.03713362536527351, 0.061162195013124726, 0.015031722452019667, -0.0008893943987002497, -0.019050464090984945, 0.0432868040805849, 0.04117903858410002, 0.020365453407162545, 0.049335837617419456, 0.039601194582206664, -0.01707217891376146, -0.04013172276120394, 0.042504924818897095, -0.013014466641984565, -0.01829275340263861, 0.019928719503987828, 0.021195823220018766, 0.008642876659275456, 0.011279526740033203, -0.002524971962022183, -0.017546600918914017, -0.011300684425338091, -0.012622784949443215, 0.021041794716316294, -0.019041565764136455, 0.04049027671177635, -0.2845317622073411, -0.011672975444240933, -0.02797371006809366, 0.015830219666273265, 0.016118817704709455, -0.0005473303902840097, -0.017106806726258243, -0.03330693054164369, 0.06415545973441726, 0.005583166648495226, -0.008639307274908765, 0.008166946263351777, 0.010566882996084373, 0.004705643070224087, -0.009145196266804096, -0.06884155768648698, 0.01993357644600195, -0.03192104148573291, -0.015570295266237327, -0.020477293943980453, -0.03139964477373433, 0.02357162535373661, -0.06267764065719363, 0.030649065227231705, -0.011572980680453098, -0.014032005354215523, 0.04039543460531584, 0.033492489300605534, -0.03450822806687381, -0.014815099718098872, -0.01642453117692415, 0.03590093105535328, 0.004719802044224125, -0.02599195638945324, 0.02409369288534955, -0.0343719